insert into articles (id, lang, region, category, title, body, source) values
  ('overtime', 'vi', null, 'payroll', 'Cách tính lương tăng ca', 'Lương giờ bằng lương tháng chia 176 giờ chuẩn. Mỗi giờ tăng ca đã được duyệt tính bằng 1,5 lần lương giờ. Ví dụ lương tháng 17.600.000 VND thì lương giờ là 100.000 VND, 8 giờ tăng ca được cộng 1.200.000 VND. Chỉ đơn tăng ca đã được HR duyệt mới được tính.', 'payroll_saga.dart'),
  ('overtime', 'en', null, 'payroll', 'How overtime pay is calculated', 'Hourly pay is the monthly salary divided by 176 standard hours. Each approved overtime hour is paid at 1.5 times the hourly rate. For example, a monthly salary of 17,600,000 VND gives 100,000 VND per hour, so 8 overtime hours add 1,200,000 VND. Only overtime requests approved by HR are paid.', 'payroll_saga.dart'),
  ('deductions', 'vi', null, 'payroll', 'Tỷ lệ khấu trừ ước tính theo nước', 'Lương thực nhận bằng lương gộp trừ khấu trừ ước tính: Việt Nam 10,5%, Đức 38%, Mỹ 25%, Brazil 27%, Nam Phi 26%, Úc 28%. Đây là tỷ lệ mô phỏng trong đồ án, chưa phải biểu thuế thật của từng nước.', 'payroll_saga.dart'),
  ('deductions', 'en', null, 'payroll', 'Estimated deduction rates by country', 'Net pay is gross pay minus an estimated deduction: Vietnam 10.5%, Germany 38%, United States 25%, Brazil 27%, South Africa 26%, Australia 28%. These rates are simulated for the project and are not the real tax tables.', 'payroll_saga.dart'),
  ('payroll-close', 'vi', null, 'payroll', 'Quy trình chốt lương hằng tháng', 'Bộ phận tài chính bấm chốt lương cho một kỳ. Hệ thống khóa kỳ ở chấm công, lấy giờ công và tỷ giá, tính phiếu lương nháp, giữ ngân sách lương ở tài chính, rồi chi qua ngân hàng. Sau khi chi: ghi chi phí lương, gửi phiếu lương cho từng nhân viên và mở khóa kỳ. Ngân hàng lỗi trước khi chi thì hệ thống tự hoàn tác; trường hợp không tự xử lý được sẽ chuyển trạng thái Cần xử lý tay và báo cho tài chính.', 'ADR 0025'),
  ('payroll-close', 'en', null, 'payroll', 'Monthly payroll closing process', 'Finance starts payroll closing for a period. The system locks the period in attendance, collects hours and exchange rates, calculates draft payslips, reserves the payroll budget in finance, then pays through the bank. After paying it records the payroll expense, sends each employee a payslip and unlocks the period. If the bank fails before paying, the system rolls back automatically; cases it cannot resolve become Needs attention and finance is notified.', 'ADR 0025'),
  ('period-lock', 'vi', null, 'attendance', 'Vì sao không duyệt được đơn khi đang chốt lương', 'Trong lúc kỳ lương đang được chốt, đơn nghỉ và đơn tăng ca thuộc kỳ đó tạm thời không duyệt được (app báo kỳ đang chốt lương). Việc này giữ cho số giờ đã dùng để tính lương không bị thay đổi giữa chừng. Chốt xong hoặc hoàn tác xong thì duyệt lại bình thường.', 'ADR 0025'),
  ('period-lock', 'en', null, 'attendance', 'Why requests cannot be approved during payroll closing', 'While a payroll period is being closed, leave and overtime requests in that period cannot be approved (the app says the period is being closed). This keeps the hours used for pay from changing midway. Once closing finishes or is rolled back, approvals work again.', 'ADR 0025'),
  ('leave', 'vi', null, 'attendance', 'Xin nghỉ phép', 'Nhân viên tạo đơn nghỉ trong mục Chấm công và nghỉ phép, chọn ngày bắt đầu, ngày kết thúc, loại nghỉ và lý do. Đơn trùng thời gian với đơn khác sẽ bị từ chối. HR hoặc quản lý duyệt đơn; không ai được tự duyệt đơn của chính mình. Kết quả duyệt được báo qua thông báo trong app.', 'attendance'),
  ('leave', 'en', null, 'attendance', 'Requesting leave', 'Employees create a leave request under Attendance and leave, choosing start date, end date, leave type and reason. Requests overlapping another request are rejected. HR or a manager decides; nobody can approve their own request. The decision is sent as an in-app notification.', 'attendance'),
  ('clock', 'vi', null, 'attendance', 'Chấm công vào và ra ca', 'Màn Chấm công có một nút: lần bấm đầu là vào ca, lần sau là ra ca, hệ thống tự biết dựa vào lịch sử trong ngày. Vừa vào ca phải chờ ít nhất 5 phút mới ra ca được. Sau khi ra ca, app hiện tổng số giờ làm trong ngày.', 'R25'),
  ('clock', 'en', null, 'attendance', 'Clocking in and out', 'The Attendance screen has a single button: the first tap clocks in, the next clocks out, based on today''s history. You must wait at least 5 minutes after clocking in before clocking out. After clocking out the app shows the total hours worked today.', 'R25'),
  ('overtime-request', 'vi', null, 'attendance', 'Đăng ký tăng ca', 'Nhân viên đăng ký tăng ca theo ngày và số giờ kèm lý do. HR duyệt hoặc từ chối; chỉ giờ tăng ca đã duyệt mới được tính lương với hệ số 1,5.', 'attendance'),
  ('overtime-request', 'en', null, 'attendance', 'Requesting overtime', 'Employees request overtime by date and hours with a reason. HR approves or rejects; only approved overtime hours are paid at 1.5 times the hourly rate.', 'attendance'),
  ('hiring', 'vi', null, 'recruitment', 'Quy trình tuyển dụng và nhận việc', 'Hồ sơ ứng viên đi qua các bước: đã nộp, AI tóm tắt, sàng lọc, phỏng vấn, mời nhận việc. Khi HR bấm Nhận vào làm, hệ thống tạo hồ sơ nhân viên và đổi tài khoản ứng viên thành tài khoản nhân viên; email ứng viên là tên đăng nhập. Người chưa có tài khoản được cấp mật khẩu tạm và phải đổi ở lần đăng nhập đầu.', 'ADR 0018'),
  ('hiring', 'en', null, 'recruitment', 'Recruitment and onboarding', 'Candidates move through submitted, AI summarised, screening, interview and offer. When HR clicks Hire, the system creates the employee record and turns the candidate account into an employee account; the candidate''s email is the login. People without an account get a temporary password that must be changed at first sign-in.', 'ADR 0018'),
  ('privacy', 'vi', null, 'security', 'Dữ liệu cá nhân được bảo vệ thế nào', 'Dữ liệu cá nhân (tên, email, số điện thoại, lương, tài khoản) được lưu ở khu vực của nước bạn. Bản sao trên kho tổng của tập đoàn được mã hóa theo khóa riêng của từng nước, nên nước khác và nhà cung cấp đám mây không đọc được. Mọi thay đổi quan trọng được ghi vào sổ kiểm toán không sửa được.', 'ADR 0026'),
  ('privacy', 'en', null, 'security', 'How personal data is protected', 'Personal data (name, email, phone, salary, account) is stored in your country''s region. The copy in the group data warehouse is encrypted with a key per country, so other countries and the cloud provider cannot read it. Important changes are written to a tamper-evident audit log.', 'ADR 0026'),
  ('notifications', 'vi', null, 'app', 'Thông báo trong app và thông báo đẩy', 'Đơn được duyệt, phiếu lương mới, hồ sơ ứng tuyển chuyển bước đều có thông báo trong mục Thông báo. Nếu bạn cho phép, điện thoại còn nhận thông báo đẩy ngay cả khi app đang tắt.', 'ADR 0019'),
  ('notifications', 'en', null, 'app', 'In-app and push notifications', 'Approved requests, new payslips and application status changes appear under Notifications. If you allow it, your phone also receives push notifications even when the app is closed.', 'ADR 0019')
